import app from 'flarum/admin/app';
import SettingsPage from './components/SettingsPage';
import LinkButton from 'flarum/common/components/LinkButton';
app.initializers.add('foskym/flarum-custom-levels', () => {
  app.registry.for('foskym-custom-levels').registerPage(SettingsPage).registerSetting(function () {
    return m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.levelText')), m("div", {
      class: "helpText"
    }, app.translator.trans('foskym-custom-levels.admin.settings.levelDesc')), m("input", {
      type: "text",
      className: "FormControl",
      bidi: this.setting('foskym-custom-levels.levelText'),
      placeholder: app.translator.trans('foskym-custom-levels.lib.defaults.level')
    }));
  }).registerSetting(function () {
    return m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.expText')), m("div", {
      class: "helpText"
    }, app.translator.trans('foskym-custom-levels.admin.settings.expDesc')), m("input", {
      type: "text",
      className: "FormControl",
      bidi: this.setting('foskym-custom-levels.expText'),
      placeholder: app.translator.trans('foskym-custom-levels.lib.defaults.exp')
    }));
  }).registerSetting(function () {
    return m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.expTooltip')), m("div", {
      class: "helpText"
    }, app.translator.trans('foskym-custom-levels.admin.settings.expTooltipDesc')), m("input", {
      type: "text",
      className: "FormControl",
      bidi: this.setting('foskym-custom-levels.expTooltip'),
      placeholder: app.translator.trans('foskym-custom-levels.lib.defaults.tooltip')
    }));
  }).registerPermission({
    icon: 'fas fa-level-up-alt',
    label: app.translator.trans('foskym-custom-levels.admin.permissions.edit_exp'),
    permission: 'user.edit_exp'
  }, 'moderate');
  if ('xypp-forum-quests' in flarum.extensions) {
    app.registry.for('foskym-custom-levels').registerSetting(function () {
      return m("div", {
        className: "Form-group"
      }, m(LinkButton, {
        href: app.route('extension', {
          id: 'xypp-forum-quests'
        })
      }, app.translator.trans('foskym-custom-levels.admin.go_to_forum_quests')));
    });
  } else {
    app.registry.for('foskym-custom-levels').registerSetting(function () {
      return m("div", {
        className: "Form-group"
      }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.expForPost')), m("div", {
        class: "helpText"
      }, app.translator.trans('foskym-custom-levels.admin.settings.expForPostDesc')), m("input", {
        type: "text",
        className: "FormControl",
        bidi: this.setting('foskym-custom-levels.expForPost')
      }));
    }).registerSetting(function () {
      return m("div", {
        className: "Form-group"
      }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.postMinLength')), m("input", {
        type: "number",
        className: "FormControl",
        bidi: this.setting('foskym-custom-levels.postMinLength')
      }));
    }).registerSetting(function () {
      return m("div", {
        className: "Form-group"
      }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.postMaxTimes')), m("input", {
        type: "number",
        className: "FormControl",
        bidi: this.setting('foskym-custom-levels.postMaxTimes')
      }));
    }).registerSetting(function () {
      return m("div", {
        className: "Form-group"
      }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.expForDiscussion')), m("div", {
        class: "helpText"
      }, app.translator.trans('foskym-custom-levels.admin.settings.expForDiscussionDesc')), m("input", {
        type: "text",
        className: "FormControl",
        bidi: this.setting('foskym-custom-levels.expForDiscussion')
      }));
    }).registerSetting(function () {
      return m("div", {
        className: "Form-group"
      }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.discussionMaxTimes')), m("input", {
        type: "number",
        className: "FormControl",
        bidi: this.setting('foskym-custom-levels.discussionMaxTimes')
      }));
    }).registerSetting(function () {
      return m("div", {
        className: "Form-group"
      }, m("label", null, app.translator.trans('foskym-custom-levels.admin.settings.expForLike')), m("div", {
        class: "helpText"
      }, app.translator.trans('foskym-custom-levels.admin.settings.expForLikeDesc')), m("input", {
        type: "text",
        className: "FormControl",
        bidi: this.setting('foskym-custom-levels.expForLike')
      }));
    }).registerSetting({
      setting: 'foskym-custom-levels.autoRemove',
      label: app.translator.trans('foskym-custom-levels.admin.settings.autoRemove'),
      type: 'select',
      options: {
        0: app.translator.trans('foskym-custom-levels.admin.auto_remove.0'),
        1: app.translator.trans('foskym-custom-levels.admin.auto_remove.1'),
        2: app.translator.trans('foskym-custom-levels.admin.auto_remove.2')
      },
      default: '1'
    }).registerSetting({
      setting: 'foskym-custom-levels.cascadeRemove',
      label: app.translator.trans('foskym-custom-levels.admin.settings.cascadeRemove'),
      type: 'checkbox'
    });
  }
});